ALTER TABLE "financial_event" DROP CONSTRAINT "financial_event_proof_valid";--> statement-breakpoint
ALTER TABLE "financial_event" DROP CONSTRAINT "financial_event_kind_valid";--> statement-breakpoint
ALTER TABLE "financial_event" ADD CONSTRAINT "financial_event_fx_refresh_valid" CHECK ("financial_event"."kind" <> 'intent_fx_refreshed' or ("financial_event"."amount_minor" = 0 and "financial_event"."fee_minor" = 0 and "financial_event"."estimated_fee_minor" = 0 and "financial_event"."estimated_display_minor" between 0 and 1000000000000 and "financial_event"."order_id" is null and "financial_event"."capture_id" is null and "financial_event"."refund_id" is null and "financial_event"."outcome" is null));--> statement-breakpoint
ALTER TABLE "financial_event" ADD CONSTRAINT "financial_event_proof_valid" CHECK (("financial_event"."kind" in ('intent_created','intent_canceled','intent_fx_refreshed') and "financial_event"."provider" = 'planning' and "financial_event"."verification" = 'user-planning') or ("financial_event"."kind" not in ('intent_created','intent_canceled','intent_fx_refreshed') and "financial_event"."provider" = 'paypal-sandbox' and "financial_event"."verification" in ('provider-api','verified-webhook') and "financial_event"."order_id" is not null));--> statement-breakpoint
ALTER TABLE "financial_event" ADD CONSTRAINT "financial_event_kind_valid" CHECK ("financial_event"."kind" in ('intent_created','intent_canceled','intent_fx_refreshed','checkout_pending','authorized','payment_pending','captured','payment_failed','payment_canceled','refund_pending','refund_completed','refund_failed','reversal_completed'));